def sort_numbers(numbers: str) -> str:
    numerals = numbers.split()
    numeral_to_value = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    values = [numeral_to_value[numeral] for numeral in numerals]
    sorted_values = sorted(values)
