print(file_name_check("1example.dll")) # => 'No'
def has_more_than_three_digits(file_name):
    digit_count = sum(1 for char in file_name if char.isdigit())
    return digit_count > 3

def has_exactly_one_dot(file_name):
    dot_count = file_name.count('.')
    return dot_count == 1

def starts_with_letter(file_name):
    first_char = file_name.split('.')[0][0]
    return first_char.isalpha()

def ends_with_valid_extension(file_name):
    valid_extensions = ['txt', 'exe', 'dll']
    extension = file_name.split('.')[-1]
    return extension in valid_extensions

def file_name_check(file_name):
    if has_more_than_three_digits(file_name) or not has_exactly_one_dot(file_name) or not starts_with_letter(file_name) or not ends_with_valid_extension(file_name):
        return 'No'
    return 'Yes'
def file_name_check(file_name):
    if len(file_name) == 0:
