    count = 0
    for char in file_name:
        if char.isdigit():
            count += 1
            if count > 3:
                return 'No'

    if file_name.count('.') != 1:
        return 'No'

    parts = file_name.split('.')
    if len(parts[0]) == 0 or not parts[0][0].isalpha():
        return 'No'

    valid_extensions = ['txt', 'exe', 'dll']
    if len(parts) < 2 or parts[1] not in valid_extensions:
        return 'No'

