import math

def triangle_area(a, b, c):
    # Step 1: Validate input
    if not all(isinstance(side, int) and side > 0 for side in [a, b, c]):
        return -1

    # Step 4: Check if valid triangle
    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    # Step 2: Calculate the perimeter
    perimeter = a + b + c

    # Step 3: Calculate the area using Heron's formula
    s = perimeter / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))

    # Step 5: Round to 2 decimal points
    area = round(area, 2)

    # Step 6: Return result
    return area

