def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    planet_order = {planet: index for index, planet in enumerate(planets)}

    start_index = min(planet_order[planet1], planet_order[planet2])
    end_index = max(planet_order[planet1], planet_order[planet2])

    sorted_planets = sorted(planets[start_index+1:end_index], key=lambda x: planet_order[x])

    return tuple(sorted_planets)
def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    orbits = {"Mercury": 1, "Venus": 2, "Earth": 3, "Mars": 4, "Jupiter": 5, "Saturn": 6, "Uranus": 7, "Neptune": 8}

    if planet1 not in planets or planet2 not in planets:
        return ()

    orbit1 = orbits[planet1]
    orbit2 = orbits[planet2]

